"""Build notebooks/GWP1_notebook.ipynb: a single, self-contained, executable notebook (library inlined)."""
import re, sys
from pathlib import Path
import nbformat as nbf
import pandas as pd

ROOT = Path(__file__).resolve().parent
MODS = ["heston", "models", "lewis", "calibration", "asian_mc", "cir"]


def library_source():
    parts = []
    for m in MODS:
        src = (ROOT / "utils" / f"{m}.py").read_text()
        src = re.sub(r"^from \.(?!\s*import)\w+ import .*$", "", src, flags=re.M)   # drop intra-package imports
        src = re.sub(r"^from \. import .*$", "", src, flags=re.M)
        src = re.sub(r'^""".*?"""\n', "", src, count=1, flags=re.S)
        parts.append(f"# ---------------- {m} ----------------\n" + src.strip() + "\n")
    lib = "\n\n".join(parts)
    lib = lib.replace("DATA_FILE", "_UNUSED_DATA_FILE") if False else lib
    return "DATA_FILE = None\n\n" + lib


def embedded_data():
    df = pd.read_excel(ROOT / "data" / "option_data.xlsx")
    rows = ",\n".join("    (%d, %s, %s, '%s')" % (r["Days to maturity"], repr(float(r["Strike"])), repr(float(r["Price"])), r["Type"]) for _, r in df.iterrows())
    return "EMBEDDED_QUOTES = [\n" + rows + "\n]"


n = nbf.v4.new_notebook(); C = n.cells
md = lambda s: C.append(nbf.v4.new_markdown_cell(s)); code = lambda s: C.append(nbf.v4.new_code_cell(s))

md("""# MScFE 622 Stochastic Modeling – Group Work Project 1
**SM Energy (SM): Heston, Bates, Asian and put pricing, and CIR interest-rate scenarios**

This notebook is self-contained and executable (Python 3.10+, numpy, scipy, pandas, matplotlib). Every question below has (1) the code, (2) its output and (3) an interpretation computed from that output.
Spot S₀ = $232.90, constant risk-free rate 1.50 %, 250 trading days per year, no dividends.

| Step | Question | Section |
|---|---|---|
| 1 | a) Heston–Lewis, b) Heston–Carr-Madan, c) Asian call (20 d, ATM, +4 % fee) | Q1a, Q1b, Q1c |
| 2 | a) Bates–Lewis, b) Bates–Carr-Madan (60 d), c) 70-day put at 95 % moneyness | Q2a, Q2b, Q2c |
| 3 | a) CIR calibration to Euribor, b) 100,000 daily paths of the 12-month rate | Q3a, Q3b |

*Runtime: about 8–10 minutes on two CPU cores (set `QUICK = True` below for a 2-minute smoke test with a cruder optimiser).*""")
md("## Model library\nFourier pricing (Lewis 2001, Carr–Madan 1999), Heston/Bates characteristic functions, calibration, Monte Carlo (Andersen QE scheme with martingale correction) and CIR. Collapsed for readability; it is plain Python.")
code("import numpy as np, pandas as pd, matplotlib.pyplot as plt, os, time\nfrom IPython.display import Markdown, display\nfrom numpy.polynomial.legendre import leggauss\nfrom scipy.optimize import brentq, differential_evolution, minimize\nfrom scipy.interpolate import CubicSpline\nfrom scipy.special import ndtri\nfrom scipy.stats import norm\n" + library_source())
md("## Setup and data")
code("QUICK = False\nMAXITER = 40 if QUICK else 200\nS0, R, Q, DPY, FEE = 232.90, 0.015, 0.0, 250, 0.04\nN_MC = 100_000 if QUICK else 200_000\n"
     + embedded_data() +
     "\nfor cand in ('option_data.xlsx', 'data/option_data.xlsx', '../data/option_data.xlsx'):\n    if os.path.exists(cand):\n        ALL = pd.read_excel(cand); break\nelse:\n    ALL = pd.DataFrame(EMBEDDED_QUOTES, columns=['Days to maturity', 'Strike', 'Price', 'Type'])   # fallback: quotes embedded above\nD = {d: ALL[ALL['Days to maturity'] == d].reset_index(drop=True) for d in (15, 60, 120)}\nprint(ALL.groupby(['Days to maturity', 'Type']).size().unstack())\nT15, T20, T60, T70 = 15 / DPY, 20 / DPY, 60 / DPY, 70 / DPY\n"
     "def show(res, title):\n    print(title, f'| MSE {res[\"mse\"]:.5f} | RMSE ${res[\"rmse\"]:.4f}')\n    for k, v in zip(res['names'], res['params']): print(f'  {k:8s} {v: .5f}')\n    print(f'  Feller 2*kappa*theta - sigma^2 = {res[\"feller\"]:.4f} | parameters on a bound: {res[\"at_bounds\"] or \"none\"}')\n"
     "def fit_fig(df, res, T, title):\n    K, t, mk, md_ = df.Strike.values, df.Type.values, df.Price.values, res['model']\n    miv = np.array([implied_vol(p, S0, k, T, R, Q, x) for p, k, x in zip(mk, K, t)]); viv = np.array([implied_vol(p, S0, k, T, R, Q, x) for p, k, x in zip(md_, K, t)])\n    f, a = plt.subplots(1, 3, figsize=(17, 4.6)); f.suptitle(title)\n    for ty, c in (('C', 'tab:blue'), ('P', 'tab:red')):\n        a[0].plot(K[t == ty], mk[t == ty], 'o', c=c, label='Market ' + ('calls' if ty == 'C' else 'puts')); a[0].plot(K[t == ty], md_[t == ty], '-x', c=c, label='Model')\n    a[0].axvline(S0, ls='--', c='gray'); a[0].set(xlabel='Strike ($)', ylabel='Option price ($)', title='Price fit'); a[0].legend()\n    a[1].plot(K, miv * 100, 'bo', label='Market'); a[1].plot(K, viv * 100, 'rx', label='Model'); a[1].set(xlabel='Strike ($)', ylabel='Implied volatility (%)', title='Implied volatility'); a[1].legend()\n    a[2].bar([f'{k:g}{x}' for k, x in zip(K, t)], mk - md_); a[2].set(xlabel='Strike and type', ylabel='Market - model ($)', title='Pricing error'); a[2].tick_params(axis='x', rotation=60)\n    for x in a: x.grid(alpha=.3)\n    plt.tight_layout(); plt.show(); return float(np.nanmean(np.abs(miv - viv)))\n")
md("### Data check: put–call parity\nThe brief supplies both calls and puts. If quotes violate put–call parity, *no* arbitrage-free model can match both, so part of the fitting error is irreducible. The smallest achievable MSE is Σ(violation²)/(4·n) for n strikes.")
code("floors = {}\nfor d in (15, 60):\n    pt = parity_table(D[d], S0, R, Q, d / DPY); floors[d] = float((pt.Violation ** 2).sum() / (4 * len(pt)))\n    print(f'--- {d} days'); print(pt.round(3).to_string(index=False)); print(f'Irreducible MSE floor from parity violations: {floors[d]:.4f}\\n')")
code("display(Markdown(f\"**Interpretation.** Calls and puts are *not* mutually consistent: the parity gap reaches ${parity_table(D[15], S0, R, Q, T15).Violation.abs().max():.2f} at 15 days and ${parity_table(D[60], S0, R, Q, T60).Violation.abs().max():.2f} at 60 days, and the 60-day call prices even rise with strike at the low end (impossible without arbitrage). Any model therefore carries a floor MSE of {floors[15]:.3f} (15 d) and {floors[60]:.3f} (60 d); we compare every fit with this floor.\"))")

md("# Step 1\n## Q1a – Heston (1993) calibrated with the Lewis (2001) formula, 15-day options\nObjective: plain MSE between model and market prices over all 10 quotes (calls by the Lewis formula, puts by put–call parity). Global differential evolution followed by a bounded L-BFGS-B polish.")
code("t0 = time.time()\nL = calibrate(D[15], S0, R, Q, T15, 'heston', 'lewis', maxiter=MAXITER)\nshow(L, 'Table 1 - Heston / Lewis, 15 days')\nivL = fit_fig(D[15], L, T15, 'Figure 1 - Heston calibrated with Lewis (2001), 15 days')\nLf = calibrate(D[15], S0, R, Q, T15, 'heston', 'lewis', maxiter=MAXITER, feller='penalty')\nshow(Lf, 'Robustness - same fit with a Feller penalty (not part of the brief)')\nprint(f'{time.time() - t0:.0f}s')")
code("display(Markdown(f\"**Interpretation (Q1a).** Calibrated parameters: v0={L['params'][0]:.4f}, kappa={L['params'][1]:.3f}, theta={L['params'][2]:.4f}, sigma={L['params'][3]:.3f}, rho={L['params'][4]:.2f}. The fit has RMSE ${L['rmse']:.3f} (MSE {L['mse']:.4f}) against an irreducible floor of {floors[15]:.4f}, so {floors[15] / L['mse']:.0%} of the error is the data itself, not the model. The mean absolute implied-volatility error is {ivL:.2%}. Parameters on a bound: {L['at_bounds'] or 'none'}. With only 10 quotes at one 15-day maturity, kappa and theta (long-run behaviour) are barely identified: adding a Feller penalty changes them completely (kappa={Lf['params'][1]:.2f}, theta={Lf['params'][2]:.3f}) while the MSE moves only from {L['mse']:.4f} to {Lf['mse']:.4f}. The identified quantities are the starting variance v0, the vol-of-vol sigma and the strongly negative correlation rho (downside skew). We therefore judge the calibration by prices, not by individual parameters.\"))")
md("## Q1b – Heston (1993) calibrated with Carr–Madan (1999), 15-day options\nSame data, objective and optimiser; only the pricing transform changes (damping factor α = 1.5).")
code("CMr = calibrate(D[15], S0, R, Q, T15, 'heston', 'cm', maxiter=MAXITER)\nshow(CMr, 'Table 2 - Heston / Carr-Madan, 15 days')\nivC = fit_fig(D[15], CMr, T15, 'Figure 2 - Heston calibrated with Carr-Madan (1999), 15 days')\ncmp = pd.DataFrame({'Lewis': np.append(L['params'], L['mse']), 'Carr-Madan': np.append(CMr['params'], CMr['mse'])}, index=L['names'] + ['MSE']); print(cmp.round(5))\nK15 = D[15].Strike.values.astype(float); p1 = L['params']\ngap = np.max(np.abs(lewis_call(S0, K15, T15, R, Q, p1) - cm_call(S0, K15, T15, R, Q, p1)))\nprint(f'Largest price gap between the two pricers at identical parameters: ${gap:.5f}')")
code("display(Markdown(f\"**Interpretation (Q1b).** Both transforms are exact representations of the same Heston price, and at identical parameters they differ by at most ${gap:.4f}. Consequently the two calibrations reach the same fit (MSE {L['mse']:.5f} vs {CMr['mse']:.5f}). The *parameters* nevertheless differ (e.g. kappa {L['params'][1]:.2f} vs {CMr['params'][1]:.2f}) because the objective is almost flat in kappa and theta at a 15-day horizon; the optimiser stops at different points of the same flat valley. The well-identified parameters (v0 {L['params'][0]:.3f} vs {CMr['params'][0]:.3f}, sigma {L['params'][3]:.2f} vs {CMr['params'][3]:.2f}, rho {L['params'][4]:.2f} vs {CMr['params'][4]:.2f}) agree closely. Similar prices, not necessarily similar parameters, is the correct expectation.\"))")
md("## Q1c – Asian call, ATM, 20 days: risk-neutral Monte Carlo and 4 % fee\nPayoff max(mean(S₀, S₁, …, S₂₀) − K, 0) with **S₀ included** in the average (21 fixings), K = S₀, 20 daily steps, 200,000 paths (100,000 antithetic pairs), QE scheme, parameters from Q1a.")
code("def mc(p, K, T, n, payoff, model='heston', **kw):\n    m, se, ci = simulate(S0, K, T, R, Q, p, n, N_MC, 42, model, payoff, **kw); return m, se, ci\nfair, se, ci = mc(p1, S0, T20, 20, 'asian_call')\neu, eus = mc(p1, S0, T20, 20, 'asian_call', scheme='euler'), None\nalt = {'QE, parameters of Q1a': (fair, se, ci), 'Euler, parameters of Q1a': eu,\n       'QE, Carr-Madan parameters (Q1b)': mc(CMr['params'], S0, T20, 20, 'asian_call'), 'QE, Feller-penalised parameters': mc(Lf['params'], S0, T20, 20, 'asian_call'),\n       'QE, S0 wrongly excluded': mc(p1, S0, T20, 20, 'asian_call', include_s0=False)}\nvanilla = float(lewis_call(S0, S0, T20, R, Q, p1)[0]); ec = mc(p1, S0, T20, 20, 'call')\nprint('Table 3 - Asian call (fair value, std. error, 95% CI, client price incl. 4% fee)')\nfor k, (m_, s_, c_) in alt.items(): print(f'  {k:34s} ${m_:.4f} +/- {s_:.4f}  CI [{c_[0]:.4f}, {c_[1]:.4f}]  client ${m_ * (1 + FEE):.4f}')\nprint(f'\\nVanilla ATM call (Lewis, closed form): ${vanilla:.4f}   MC European call: ${ec[0]:.4f} +/- {ec[1]:.4f} (validation z = {(ec[0] - vanilla) / ec[1]:+.1f})')\nprint(f'FAIR PRICE ${fair:.4f} | fee 4% ${fair * FEE:.4f} | CLIENT PAYS ${fair * (1 + FEE):.4f}')\nconv = [(n_, *simulate(S0, S0, T20, R, Q, p1, 20, n_, 42, 'heston', 'asian_call')[:2]) for n_ in (5_000, 10_000, 25_000, 50_000, 100_000, 200_000)]\nplt.figure(figsize=(7, 4)); plt.errorbar([c[0] for c in conv], [c[1] for c in conv], yerr=[1.96 * c[2] for c in conv], fmt='o-', capsize=3); plt.xscale('log'); plt.xlabel('Number of simulated paths'); plt.ylabel('Asian call price ($)'); plt.title('Figure 3 - Monte Carlo convergence (95% interval)'); plt.grid(alpha=.3); plt.show()")
code("display(Markdown(f\"**Interpretation (Q1c).** Fair value of the 20-day ATM Asian call: **${fair:.2f}** (95% CI ${ci[0]:.2f}–${ci[1]:.2f}). The bank adds a **4% fee of ${fair * FEE:.2f}**, so the client pays **${fair * (1 + FEE):.2f}**. A vanilla ATM call costs ${vanilla:.2f}; the Asian is {1 - fair / vanilla:.0%} cheaper because averaging dampens volatility. The simulation reproduces the closed-form vanilla price (z = {(ec[0] - vanilla) / ec[1]:+.1f}), which validates the scheme; the cruder Euler scheme differs by ${abs(eu[0] - fair):.3f}. Using the other calibrations changes the price by at most ${max(abs(v[0] - fair) for v in alt.values()):.2f}, so the *price* is robust even though the parameters are not. Leaving S₀ out of the average would misstate the price by ${abs(alt['QE, S0 wrongly excluded'][0] - fair):.2f}.\"))")
md("**Plain-language summary for the client (Q1c.iii).** We looked at how the market currently prices ordinary options on SM with about two weeks to expiry and found a set of assumptions about how SM's price and its day-to-day swings behave that reproduces those prices closely. We then ran 200,000 possible daily price stories for the next 20 trading days, calculated for each the average price over the period (including today's price), and what your option would pay if that average ends above today's price. The fair price is the average of those payoffs, discounted at the 1.50% rate. We add a 4% fee. Because the option depends on an *average*, it is cheaper than an ordinary option but also pays out less in extreme moves. The result depends on assumptions we cannot observe directly, so the price is quoted with a margin of a few cents.")

md("# Step 2\n## Q2a – Bates (1996) calibrated with Lewis (2001), 60-day options\nBates adds log-normal jumps (intensity λ, mean log-jump μ_J, jump volatility δ_J) to Heston. Eight parameters are fitted to 10 quotes, with the same plain-MSE objective; the Heston fit at 60 days is the benchmark.")
code("t0 = time.time()\nBL = calibrate(D[60], S0, R, Q, T60, 'bates', 'lewis', maxiter=MAXITER); show(BL, 'Table 4 - Bates / Lewis, 60 days')\nivB = fit_fig(D[60], BL, T60, 'Figure 4 - Bates calibrated with Lewis (2001), 60 days')\nH60 = calibrate(D[60], S0, R, Q, T60, 'heston', 'lewis', maxiter=MAXITER); show(H60, 'Benchmark - Heston / Lewis, 60 days')\nBLf = calibrate(D[60], S0, R, Q, T60, 'bates', 'lewis', maxiter=MAXITER, feller='penalty'); show(BLf, 'Robustness - Bates with Feller penalty')\nprint(f'{time.time() - t0:.0f}s')")
code("display(Markdown(f\"**Interpretation (Q2a).** Bates reaches RMSE ${BL['rmse']:.3f} (MSE {BL['mse']:.3f}) against Heston ${H60['rmse']:.3f} (MSE {H60['mse']:.3f}); the irreducible parity floor is {floors[60]:.3f}. Jumps therefore improve the fit by only {1 - BL['mse'] / H60['mse']:.1%}: {floors[60] / BL['mse']:.0%} of the remaining error comes from the inconsistent call and put quotes, which no model can remove. The estimated correlation is rho = {BL['params'][4]:+.2f}; a *positive* value is atypical for an equity and reflects the parity violations that grow with strike, not leverage effects. Parameters on bounds: {BL['at_bounds'] or 'none'}. With eight parameters and ten noisy quotes the individual values are weakly identified (the Feller-penalised fit has MSE {BLf['mse']:.3f} with very different parameters), so the jump block should not be given a structural interpretation.\"))")
md("## Q2b – Bates (1996) calibrated with Carr–Madan (1999), 60-day options")
code("BC = calibrate(D[60], S0, R, Q, T60, 'bates', 'cm', maxiter=MAXITER); show(BC, 'Table 5 - Bates / Carr-Madan, 60 days')\nfit_fig(D[60], BC, T60, 'Figure 5 - Bates calibrated with Carr-Madan (1999), 60 days')\nprint(pd.DataFrame({'Lewis': np.append(BL['params'], BL['mse']), 'Carr-Madan': np.append(BC['params'], BC['mse'])}, index=BL['names'] + ['MSE']).round(5))\nK60 = D[60].Strike.values.astype(float); gapB = np.max(np.abs(lewis_call(S0, K60, T60, R, Q, BL['params'], 'bates') - cm_call(S0, K60, T60, R, Q, BL['params'], 'bates')))\nprint(f'Largest Lewis vs Carr-Madan price gap at identical Bates parameters: ${gapB:.5f}')")
code("display(Markdown(f\"**Interpretation (Q2b).** MSE is {BL['mse']:.5f} (Lewis) vs {BC['mse']:.5f} (Carr-Madan), and at identical parameters the two transforms differ by ${gapB:.4f}: the same price function, hence the same fit. Parameter values can differ because eight parameters are only loosely pinned down by ten quotes (largest gap {np.abs(BL['params'] - BC['params']).max():.2f}); compare prices and MSE rather than individual parameters.\"))")
md("## Q2c – European put, 70 days, strike = 95 % of S₀: Monte Carlo and 4 % fee\nPriced by Monte Carlo under the Bates dynamics calibrated in Q2a (jumps simulated), 70 daily steps, validated against the Fourier price. A 60-day calibration is the closest available to the 70-day maturity (quotes exist at 15, 60 and 120 days).")
code("Kp = 0.95 * S0\nsets = {'Bates, Lewis calibration (headline)': ('bates', BL['params']), 'Bates, Carr-Madan calibration': ('bates', BC['params']), 'Bates, Feller-penalised': ('bates', BLf['params']),\n        'Heston 60d': ('heston', H60['params']), 'Heston 15d (too short-dated)': ('heston', p1)}\nrows = []\nfor k, (mdl, pp) in sets.items():\n    m_, s_, c_ = simulate(S0, Kp, T70, R, Q, pp, 70, N_MC, 42, mdl, 'put'); fo = float(model_price(S0, Kp, T70, R, Q, pp, 'P', mdl)[0])\n    rows.append((k, m_, s_, fo, (m_ - fo) / s_, m_ * (1 + FEE)))\nprint(f'Table 6 - 70-day put, strike ${Kp:.2f}'); print(pd.DataFrame(rows, columns=['Model', 'MC price', 'MC s.e.', 'Fourier price', 'z', 'Client price (+4%)']).round(4).to_string(index=False))\nput, put_se = rows[0][1], rows[0][2]\npay = simulate(S0, Kp, T70, R, Q, BL['params'], 70, N_MC, 42, 'bates', 'put', return_payoffs=True)[1]\nplt.figure(figsize=(7, 4)); plt.hist(pay[pay > 0], 60, color='tab:red', alpha=.8); plt.xlabel('Discounted put payoff ($)'); plt.ylabel('Number of paths'); plt.title(f'Figure 6 - positive payoffs ({(pay == 0).mean():.0%} of paths expire worthless)'); plt.grid(alpha=.3); plt.show()")
code("display(Markdown(f\"**Interpretation (Q2c).** The put (strike ${Kp:.2f}) has a fair value of **${put:.2f}** (± {1.96 * put_se:.2f}); with the 4% fee (${put * FEE:.2f}) the client pays **${put * (1 + FEE):.2f}**; break-even at expiry is ${Kp - put:.2f}. The simulation agrees with the Fourier price (z = {rows[0][4]:+.1f}). Across calibrations the put ranges from ${min(r_[1] for r_ in rows[:4]):.2f} to ${max(r_[1] for r_ in rows[:4]):.2f}, a model-risk spread of ${max(r_[1] for r_ in rows[:4]) - min(r_[1] for r_ in rows[:4]):.2f} that should be covered by a reserve; the 15-day parameters give ${rows[4][1]:.2f} and are not suitable for this maturity.\"))")
md("**Plain-language summary for the client (Q2c).** A put option is insurance: you pay a premium now, and if SM's price on the expiry date (70 trading days away) is below the protection level of 95% of today's price, you are compensated for the shortfall. We estimated the premium by simulating 200,000 possible futures for the stock, including occasional sudden jumps, and averaging the insurance payouts. Most futures end above the protection level and pay nothing; a minority pay a lot. The premium plus our 4% fee is the amount shown above. If SM falls by more than the premium, the insurance has paid for itself.")

md("# Step 3\n## Q3a – CIR (1985) calibrated to the Euribor term structure\n**Term structure.** Euribor quotes are *simple* rates, so the discount factor is P = 1/(1+L·τ) and the continuously compounded zero rate is ln(1+Lτ)/τ. A cubic spline through the five zero rates gives 52 weekly points over 12 months. CIR parameters (κ, θ, σ) minimise the squared error of the model zero yield with r₀ fixed at the one-week rate and the Feller constraint 2κθ ≥ σ².")
code("ts = term_structure(); print(pd.DataFrame({'Maturity': ts['labels'], 'Euribor (simple, %)': ts['simple'] * 100, 'Discount factor': ts['discount'], 'Zero rate (cont., %)': ts['zero'] * 100}).round(4).to_string(index=False))\ncr = calibrate_cir('zero')\nprint(f\"\\nTable 7 - CIR: kappa={cr['kappa']:.4f}  theta={cr['theta']:.4%}  sigma={cr['sigma']:.3f}  r0={cr['r0']:.3%}  RMSE={cr['rmse_bp']:.2f} bp  Feller margin={cr['feller']:.4f}\")\nprint(f\"sigma plateau (RMSE within 0.02 bp of best): {cr['plateau'][0]:.2f} - {cr['plateau'][1]:.2f}\")\nf, a = plt.subplots(1, 3, figsize=(17, 4.4))\na[0].plot(MAT * 12, ts['zero'] * 100, 'ro', label='Euribor zero rates'); a[0].plot(cr['t'] * 12, cr['market'] * 100, 'g--', label='Cubic spline (weekly)'); a[0].plot(cr['t'] * 12, cr['model'] * 100, 'b', label='CIR')\na[0].set(xlabel='Maturity (months)', ylabel='Zero rate (%)', title='Figure 7a - CIR fit'); a[0].legend()\na[1].bar(cr['t'] * 12, (cr['market'] - cr['model']) * 1e4, width=.18); a[1].axhline(0, c='k'); a[1].set(xlabel='Maturity (months)', ylabel='Spline - CIR (bp)', title='Figure 7b - residuals')\na[2].plot(cr['profile'][:, 0], cr['profile'][:, 3], 'o-'); a[2].set(xlabel='Fixed sigma', ylabel='Best-fit RMSE (bp)', title='Figure 7c - sigma is not identified by the curve')\nfor x in a: x.grid(alpha=.3)\nplt.tight_layout(); plt.show()")
code("display(Markdown(f\"**Interpretation (Q3a).** Fitted CIR: speed of mean reversion kappa = {cr['kappa']:.2f}, long-run level theta = {cr['theta']:.2%}, volatility sigma = {cr['sigma']:.2f}, starting rate r0 = {cr['r0']:.3%}. The model reproduces the curve with an RMSE of {cr['rmse_bp']:.1f} bp (largest miss around the 1-month kink of the spline). kappa and theta are determined by the *slope* of the curve and imply a long-run rate far above the observed 12-month level because the curve is steep: they are an extrapolation beyond 12 months. sigma is essentially **not identified** by a yield curve (Figure 7c: the fit is equally good for sigma between {cr['plateau'][0]:.2f} and {cr['plateau'][1]:.2f}); we use the midpoint of that plateau and test sensitivity to it in Q3b.\"))")
md("## Q3b – 100,000 daily Monte Carlo paths of the 12-month Euribor over one year\nExact CIR transitions (non-central chi-square) on 250 daily steps; on each day the 12-month Euribor is the CIR one-year yield at the simulated short rate, converted back to a simple rate.")
code("sim = simulate_cir_paths(cr['r0'], cr['kappa'], cr['theta'], cr['sigma'], n=100_000)\nLend = sim['terminal_L12']; qi = list(sim['qs']); E = Lend.mean(); cur = QUOTES[-1]\nci = {c: np.quantile(Lend, [(1 - c) / 2, (1 + c) / 2]) for c in (.90, .95, .99)}\nlo95, hi95 = sim['quantiles'][:, qi.index(.025)], sim['quantiles'][:, qi.index(.975)]\nprint(f'Expected 12M Euribor in 1 year: {E:.3%} (sd {Lend.std():.3%}); today: {cur:.3%}; P(higher than today) = {(Lend > cur).mean():.1%}')\nfor c, v in ci.items(): print(f'  {c:.0%} range at the 1-year horizon: [{v[0]:.3%}, {v[1]:.3%}]')\nprint(f'  95% envelope over the whole year: [{lo95.min():.3%}, {hi95.max():.3%}]   absolute min/max of all 100,000 paths: [{sim[\"path_min\"].min():.3%}, {sim[\"path_max\"].max():.3%}]')\nf, a = plt.subplots(1, 2, figsize=(15, 4.6))\nfor j in range(40): a[0].plot(sim['days'], sim['samples'][:, j] * 100, lw=.5, alpha=.5)\na[0].fill_between(sim['days'], lo95 * 100, hi95 * 100, color='k', alpha=.15, label='95% band'); a[0].plot(sim['days'], sim['mean'] * 100, 'r', lw=2, label='Mean'); a[0].set(xlabel='Trading day', ylabel='12-month Euribor (%)', title='Figure 8a - simulated paths and 95% band'); a[0].legend()\na[1].hist(Lend * 100, 80, density=True, alpha=.8); a[1].axvline(E * 100, c='r', ls='--', label='Expected value'); a[1].axvline(cur * 100, c='k', ls=':', label='Today'); [a[1].axvline(x * 100, c='purple', ls=':') for x in ci[.95]]\na[1].set(xlabel='12-month Euribor in one year (%)', ylabel='Density', title='Figure 8b - distribution at the 1-year horizon (95% range dotted)'); a[1].legend()\nfor x in a: x.grid(alpha=.3)\nplt.tight_layout(); plt.show()\nsens = []\nfor s_ in (.02, .05, .10, .20, .30):\n    Lt = simulate_cir_paths(cr['r0'], cr['kappa'], cr['theta'], s_, n=20_000, n_sample=1)['terminal_L12']; sens.append((s_, Lt.mean(), *np.quantile(Lt, [.025, .975])))\nprint('\\nSensitivity of the answer to the unidentified sigma'); print(pd.DataFrame(sens, columns=['sigma', 'Expected', '2.5%', '97.5%']).round(4).to_string(index=False))")
code("rows = {'Brief constant 1.50%': R, 'Today 12M Euribor': cur, 'Expected 12M in 1 year': E}\nimp = []\nfor nm, rr in rows.items():\n    a_ = simulate(S0, S0, T20, rr, Q, p1, 20, 100_000, 7, 'heston', 'asian_call')[0]; p_ = simulate(S0, Kp, T70, rr, Q, BL['params'], 70, 100_000, 7, 'bates', 'put')[0]\n    imp.append((nm, rr, a_, p_, 1 / (1 + rr)))\nimp = pd.DataFrame(imp, columns=['Rate used', 'r', 'Asian call 20d', 'Put 70d', '1-year discount factor']); print('Table 8 - product prices at different rate levels (same random numbers)'); print(imp.round(4).to_string(index=False))\nd_ = imp.set_index('Rate used'); dA = d_.loc['Expected 12M in 1 year', 'Asian call 20d'] - d_.loc['Today 12M Euribor', 'Asian call 20d']; dP = d_.loc['Expected 12M in 1 year', 'Put 70d'] - d_.loc['Today 12M Euribor', 'Put 70d']")
code("display(Markdown(f\"**Interpretation (Q3b).** (i) At 95% confidence the 12-month Euribor one year from now lies between **{ci[.95][0]:.2%} and {ci[.95][1]:.2%}** (99%: {ci[.99][0]:.2%}–{ci[.99][1]:.2%}); across the whole year the 95% band spans {lo95.min():.2%}–{hi95.max():.2%} and the extreme simulated values are {sim['path_min'].min():.2%} and {sim['path_max'].max():.2%}. These widths scale with sigma, which the curve cannot identify (see sensitivity table); the 95% range varies from ±{(sens[0][3] - sens[0][2]) / 2:.1%} at sigma = 0.02 to ±{(sens[-1][3] - sens[-1][2]) / 2:.1%} at sigma = 0.30. (ii) The **expected 12-month Euribor in one year is {E:.2%}** versus {cur:.3%} today (+{(E - cur) * 1e4:.0f} bp), and it is robust to sigma (it moves by less than 0.01 pp across the table). It reflects the steep current curve extrapolated by the fitted model; plausible alternative fits of the same curve give {cr_ev_lo:.1%}–{cr_ev_hi:.1%}. (iii) A higher rate raises call values and lowers put values and discount factors: moving from today's rate to the expected rate changes the 20-day Asian call by ${dA:+.3f} and the 70-day put by ${dP:+.3f}; one-year discounting falls from {d_.loc['Today 12M Euribor', '1-year discount factor']:.4f} to {d_.loc['Expected 12M in 1 year', '1-year discount factor']:.4f}. For short-dated products the effect is small compared with the volatility assumptions; for fixed-rate commitments or one-year funding it is material. The model is fitted to today's curve, i.e. under risk-neutral pricing, so these are scenarios, not statistical forecasts.\"))".replace("{cr_ev_lo:.1%}", "{NEAR[0]:.1%}").replace("{cr_ev_hi:.1%}", "{NEAR[1]:.1%}"))
md("# Conclusions\nSee the interpretation under each question. Headline results are printed in the cell below.")
code("display(Markdown(f\"* **Q1a/b (Heston, 15 d):** RMSE ${L['rmse']:.2f} (Lewis) / ${CMr['rmse']:.2f} (Carr-Madan); identical prices, non-identical kappa/theta.\\n* **Q1c (Asian ATM 20 d):** fair **${fair:.2f}**, client price **${fair * (1 + FEE):.2f}** (4% fee).\\n* **Q2a/b (Bates, 60 d):** RMSE ${BL['rmse']:.2f} vs Heston ${H60['rmse']:.2f}; most residual error is put–call inconsistency in the quotes.\\n* **Q2c (put 70 d, K = ${Kp:.2f}):** fair **${put:.2f}**, client price **${put * (1 + FEE):.2f}**.\\n* **Q3 (CIR):** expected 12M Euribor in 1 year **{E:.2%}** (95% range {ci[.95][0]:.2%}–{ci[.95][1]:.2%}) vs {cur:.3%} today.\"))")
md("# References (MLA)\nAndersen, Leif B. G. “Simple and Efficient Simulation of the Heston Stochastic Volatility Model.” *Journal of Computational Finance*, vol. 11, no. 3, 2008, pp. 1–42.\n\nBates, David S. “Jumps and Stochastic Volatility: Exchange Rate Processes Implicit in Deutsche Mark Options.” *Review of Financial Studies*, vol. 9, no. 1, 1996, pp. 69–107.\n\nCarr, Peter, and Dilip Madan. “Option Valuation Using the Fast Fourier Transform.” *Journal of Computational Finance*, vol. 2, no. 4, 1999, pp. 61–73.\n\nCox, John C., et al. “A Theory of the Term Structure of Interest Rates.” *Econometrica*, vol. 53, no. 2, 1985, pp. 385–407.\n\nHeston, Steven L. “A Closed-Form Solution for Options with Stochastic Volatility with Applications to Bond and Currency Options.” *Review of Financial Studies*, vol. 6, no. 2, 1993, pp. 327–43.\n\nLewis, Alan L. “A Simple Option Formula for General Jump-Diffusion and Other Exponential Lévy Processes.” *SSRN*, 2001, papers.ssrn.com/sol3/papers.cfm?abstract_id=282110.\n\n*For research and education only; not investment advice.*")

# NEAR (alternative CIR fits) is defined in Q3a for the interpretation
for c in C:
    if c.cell_type == "code" and "cr = calibrate_cir('zero')" in c.source:
        c.source += "\n_t, _y = weekly_curve('zero'); _ev = []\nfor _k in np.linspace(.05, 5, 100):\n    for _th in np.linspace(.005, .1, 96):\n        if cr['sigma'] ** 2 > 2 * _k * _th: continue\n        if np.sqrt(np.mean((_y - cir_yield(_k, _th, cr['sigma'], cr['r0'], _t)) ** 2)) * 1e4 <= cr['rmse_bp'] + 0.25:\n            _g, _d, _B = cir_zero_params(_k, cr['sigma'], 1.0); _lnA = (2 * _k * _th / cr['sigma'] ** 2) * np.log(2 * _g * np.exp((_k + _g) / 2) / _d)\n            _ev.append(np.expm1(-_lnA + _B * (_th + (cr['r0'] - _th) * np.exp(-_k))))\nNEAR = (min(_ev), max(_ev))   # expected 12M rate in 1y across all near-optimal (kappa, theta) pairs"
out = ROOT / "notebooks" / "GWP1_notebook.ipynb"
